def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==7]
    r0=min(r for r,c in pts); c0=min(c for r,c in pts)
    base={(r-r0,c-c0) for r,c in pts}
    shapes=set()
    for flip in (1,-1):
      for rot in range(4):
        s=set()
        for r,c in base:
          x,y=r,flip*c
          for _ in range(rot): x,y=y,-x
          s.add((x,y))
        mr=min(x for x,y in s); mc=min(y for x,y in s)
        shapes.add(frozenset((x-mr,y-mc) for x,y in s))
    for shape in shapes:
      sh=max(r for r,c in shape)+1; sw=max(c for r,c in shape)+1
      for a in range(h-sh+1):
        for b in range(w-sw+1):
          loc=[(a+r,b+c) for r,c in shape]
          if any(grid[r][c]==7 for r,c in loc): continue
          if all(grid[r][c]==0 for r,c in loc):
            for r,c in loc: out[r][c]=7
    return out
